"use client";

import { useMemo, useRef, useState, type Dispatch, type SetStateAction } from "react";
import { CollapsibleSection } from "@/components/ui/collapsible";
import { resolveAuthorityOutcome, resolveDrugOutcome, resolvePublicSafetyOutcome, resolveWeaponOutcome, seguridadPublica, seguridadPublicaBlockDescription, seguridadPublicaBlockLabel, seguridadPublicaConceptos, type AuthorityOutcome, type DrugOutcome, type ProcessualInput, type PublicConcept, type PublicSafetyFacts, type PublicSafetyOutcome, type PublicSecurityBlock, type WeaponConduct, type WeaponContextInput, type WeaponObjectInput, type WeaponOutcome } from "@/data/seguridad-publica";
import { resolvePatrimonyOutcome, type PatrimonyFacts, type PatrimonyOutcome } from "@/data/patrimonio";

type Props = { block: PublicSecurityBlock; initialConceptId?: string; onBack: () => void };
type ProcessualFactsForm = Omit<ProcessualInput, "flagrante">;
const blockIcons: Record<PublicSecurityBlock, string> = {
  "Drogas": "●",
  "Autoridad y agentes": "🛡",
  "Armas y objetos peligrosos": "⚔",
  "Violencia de género y doméstica": "◆",
  "Agresiones y lesiones": "+",
  "Agresiones sexuales": "◇",
  "Peleas y riñas": "👥",
  "Amenazas y coacciones": "!",
  "Delitos contra el patrimonio": "▣",
};
const hasProcessualAnswer = (flagrante: boolean | undefined, facts: ProcessualFactsForm, minor = false) => minor
  ? facts.domicilioConocido === true || facts.domicilioConocido === false && facts.fianzaBastante !== undefined
  : flagrante === true || flagrante === false && facts.indiciosHechoSuficientes !== undefined && (facts.indiciosHechoSuficientes === false || facts.indiciosParticipacionSuficientes !== undefined && (facts.indiciosParticipacionSuficientes === false || [facts.intentoFugaElusion, facts.identidadODomicilioNoVerificables, facts.riesgoOcultacionPruebas, facts.riesgoConcretoVictimaTestigos].every((value) => value !== undefined)));
const processualInput = (flagrante: boolean | undefined, facts: ProcessualFactsForm): ProcessualInput => ({ flagrante, ...facts });

export function SeguridadPublicaView({ block, initialConceptId, onBack }: Props) {
  const [activeBlock, setActiveBlock] = useState<PublicSecurityBlock>(block);
  const [selectedId, setSelectedId] = useState<string | undefined>(initialConceptId);
  const [query, setQuery] = useState("");
  const [facts, setFacts] = useState<PublicSafetyFacts>({});
  const blockConcepts = useMemo(() => seguridadPublicaConceptos.filter((concept) => concept.bloque === activeBlock), [activeBlock]);
  const selected = blockConcepts.find((concept) => concept.id === selectedId);
  const matches = useMemo(() => {
    const q = normalise(query);
    return q ? blockConcepts.filter((concept) => normalise([concept.titulo, ...concept.sinonimos].join(" ")).includes(q)) : [];
  }, [blockConcepts, query]);
  const choose = (id: string) => { const target = seguridadPublicaConceptos.find((concept) => concept.id === id); if (target) { setActiveBlock(target.bloque); setSelectedId(id); } setQuery(""); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const blockIcon = blockIcons[activeBlock];
  if (selected) return <ConceptSheet concept={selected} facts={facts} setFacts={setFacts} onNavigate={choose} onBack={() => setSelectedId(undefined)} />;
  return <section className="sp-view">
    <div className="sp-heading"><div><span className="kicker">{seguridadPublica.titulo.toUpperCase()}</span><h2>{seguridadPublicaBlockLabel(activeBlock)}</h2><p>{seguridadPublicaBlockDescription[activeBlock]}</p></div><button className="alcohol-back" onClick={onBack}>← Volver a Seguridad Pública</button></div>
    <section className="sp-search"><label htmlFor="public-security-search">Buscar situación</label><input id="public-security-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Ej.: porro, no se identifica, navaja…" autoComplete="off" />{query && <div className="sp-search-results">{matches.length ? matches.map((concept) => <button key={concept.id} onClick={() => choose(concept.id)}><strong>{concept.titulo}</strong><small>{seguridadPublicaBlockLabel(concept.bloque)}</small></button>) : <p>Sin concepto operativo coincidente.</p>}</div>}</section>
    <section className="sp-block"><div className="sp-block-heading"><span aria-hidden="true">{blockIcon}</span><h3>{seguridadPublicaBlockLabel(activeBlock)}</h3></div><div className="sp-concept-grid">{blockConcepts.map((concept) => <button key={concept.id} onClick={() => choose(concept.id)}><strong>{concept.titulo}</strong><small>{concept.resultado}</small><b>›</b></button>)}</div></section>
  </section>;
}

function ConceptSheet({ concept, facts, setFacts, onNavigate, onBack }: { concept: PublicConcept; facts: PublicSafetyFacts; setFacts: Dispatch<SetStateAction<PublicSafetyFacts>>; onNavigate: (id: string) => void; onBack: () => void }) {
  const sheetRef = useRef<HTMLElement>(null);
  const [copied, setCopied] = useState(false);
  const copySummary = async () => {
    const text = sheetRef.current?.innerText;
    if (!text) return;
    await navigator.clipboard.writeText(text);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1600);
  };
  return <section className="sp-view sp-view-with-actions"><button className="back sp-desktop-back" onClick={onBack}>← Volver a {seguridadPublicaBlockLabel(concept.bloque)}</button><article className="sp-sheet" ref={sheetRef}><header><span className="kicker">{seguridadPublicaBlockLabel(concept.bloque).toUpperCase()}</span><h2>{concept.titulo}</h2><p>{concept.resultado}</p></header>{concept.id === "drogas_trafico" ? <DrugDecision /> : concept.id === "patrimonio" ? <PatrimonyDecision facts={facts} setFacts={setFacts} onNavigate={onNavigate} /> : ["armas_blancas", "objetos_peligrosos"].includes(concept.id) ? <WeaponDecision key={concept.id} concept={concept} facts={facts} /> : ["desobediencia", "resistencia", "amenazas"].includes(concept.id) ? <AuthorityDecision concept={concept} /> : concept.id === "atentado" ? <AtentadoConcept concept={concept} /> : isIncidentConcept(concept.id) ? <IncidentDecision concept={concept} facts={facts} setFacts={setFacts} onNavigate={onNavigate} /> : <StaticConcept concept={concept} />}</article><nav className="sp-mobile-actions" aria-label="Acciones principales"><button onClick={onBack}>← Volver</button><button className="primary" onClick={copySummary}>{copied ? "✓ Copiado" : "Copiar resumen"}</button></nav></section>;
}

function StaticConcept({ concept }: { concept: PublicConcept }) {
  return <><OperationalSection title="Qué comprobar" items={concept.comprobar} /><ResultCard title={concept.calificacion?.startsWith("DELITO") ? "POSIBLE DELITO" : "INFRACCIÓN"} norma={concept.norma} clasificacion={concept.calificacion} range={concept.rango} text={concept.resultado} /><OperationalSection title="Actuación policial" items={concept.actuacion ?? []} />{concept.id === "identificacion" && <div className="sp-highlight neutral"><strong>TRASLADO IDENTIFICATIVO</strong><p>El traslado a dependencias a efectos exclusivos de identificación conforme al art. 16 LO 4/2015 no constituye una detención penal.</p></div>}{concept.competencia && <OperationalSection title="Competencia" items={[concept.competencia]} />}{concept.bloque === "Drogas" && <CommonProcessual showSubstance />}<LegalFoundation normas={[concept.norma, ...(concept.fuentes ?? [])]} detalle={concept.frontera} /></>;
}

function AtentadoConcept({ concept }: { concept: PublicConcept }) {
  const [flagrante, setFlagrante] = useState<boolean>();
  const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const answered = hasProcessualAnswer(flagrante, processFacts);
  const result = resolveAuthorityOutcome("resistencia", "atentado", processualInput(flagrante, processFacts))!;
  return <><OperationalSection title="Qué comprobar" items={concept.comprobar} /><ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} /><ResolvedOutcome result={result} showProcessual={answered} /></>;
}

function DrugDecision() {
  const [status, setStatus] = useState<"sin" | "duda" | "venta">("sin"); const [substance, setSubstance] = useState<"grave_dano" | "resto">("grave_dano"); const [indicators, setIndicators] = useState<string[]>([]); const [flagrante, setFlagrante] = useState<boolean>(); const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const processual = processualInput(flagrante, processFacts);
  const answered = hasProcessualAnswer(flagrante, processFacts);
  const result: DrugOutcome | null = status === "sin" ? null : status === "duda" ? resolveDrugOutcome({ ventaObservada: false, indiciosSuficientes: false, sustancia: substance, ...processual }) : resolveDrugOutcome({ ventaObservada: true, indiciosSuficientes: true, sustancia: substance, ...processual });
  return <><OperationalSection title="Qué comprobar" items={seguridadPublicaConceptos.find((item) => item.id === "drogas_trafico")?.comprobar ?? []} /><fieldset className="sp-choice"><legend>¿Se observa venta, entrega o suministro a tercero?</legend><label><input type="radio" checked={status === "sin"} onChange={() => setStatus("sin")} /> No; sin indicios suficientes de tráfico</label><label><input type="radio" checked={status === "duda"} onChange={() => setStatus("duda")} /> Hay indicios de posible tráfico, no concluyentes</label><label><input type="radio" checked={status === "venta"} onChange={() => setStatus("venta")} /> Sí, o hay indicios objetivos suficientes</label>{status === "venta" && <label className="sp-subchoice">Tipo de sustancia <select value={substance} onChange={(event) => setSubstance(event.target.value as "grave_dano" | "resto")}><option value="grave_dano">Causa grave daño a la salud</option><option value="resto">Resto de sustancias</option></select></label>}</fieldset>{status === "venta" && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} />}{status === "duda" && <fieldset className="sp-choice"><legend>Indicios concretos a documentar</legend>{trafficIndicators.map((indicator) => <label key={indicator}><input type="checkbox" checked={indicators.includes(indicator)} onChange={() => setIndicators((current) => current.includes(indicator) ? current.filter((item) => item !== indicator) : [...current, indicator])} /> {indicator}</label>)}</fieldset>}{status === "sin" ? <StaticConcept concept={seguridadPublicaConceptos.find((item) => item.id === "drogas_consumo")!} /> : result && <><ResolvedOutcome result={result} drug showProcessual={status !== "venta" || answered} />{status === "duda" && <OperationalSection title="Indicios concretos presentes" items={indicators.length ? indicators : ["Marca los indicios observados antes de documentar y coordinar la continuación con CNP."]} />}</>}</>;
}

const incidentConceptIds = ["violencia_relacional", "agresiones_lesiones", "agresiones_sexuales", "peleas_rinas", "amenazas_coacciones"];
const isIncidentConcept = (id: string) => incidentConceptIds.includes(id);

function IncidentDecision({ concept, facts, setFacts, onNavigate }: { concept: PublicConcept; facts: PublicSafetyFacts; setFacts: Dispatch<SetStateAction<PublicSafetyFacts>>; onNavigate: (id: string) => void }) {
  const [flagrante, setFlagrante] = useState<boolean>();
  const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const processual = processualInput(flagrante, processFacts);
  const set = <K extends keyof PublicSafetyFacts>(key: K, value: PublicSafetyFacts[K]) => setFacts((current) => ({ ...current, [key]: value }));
  const toggleRelationEvent = (value: NonNullable<PublicSafetyFacts["hechosRelacion"]>[number]) => setFacts((current) => ({ ...current, hechosRelacion: current.hechosRelacion?.includes(value) ? current.hechosRelacion.filter((item) => item !== value) : [...(current.hechosRelacion ?? []), value] }));
  const result = resolvePublicSafetyOutcome(concept.id, facts, processual);
  const hasProcessualOutput = Boolean(result.procesal);
  const fixedMinorOffence = result.procesal?.escenarioProcesal === "DELITO LEVE";
  const needsProcessualFacts = hasProcessualOutput && facts.autorMayorEdad !== false;
  const showResolvedProcessual = facts.autorMayorEdad === false || hasProcessualAnswer(flagrante, processFacts, fixedMinorOffence);
  const sexualContext = concept.id === "agresiones_sexuales" || facts.hechosRelacion?.includes("sexual");
  const showComplaintQuestion = sexualContext && facts.actoSexualNoConsentido === true;
  return <>
    <OperationalSection title="Qué comprobar" items={concept.comprobar} />
    <RelationshipQuestion facts={facts} set={set} />
    {facts.tipoRelacion && concept.id !== "violencia_relacional" && <div className="sp-highlight neutral"><strong>CONTEXTO RELACIONAL REGISTRADO</strong><p>La relación, los sexos jurídicamente relevantes y la convivencia se conservan al conectar con otros bloques.</p></div>}
    {concept.id === "violencia_relacional" && <>
      <fieldset className="sp-choice"><legend>¿Qué hechos pueden coexistir?</legend>{relationEvents.map(([value, label]) => <label key={value}><input type="checkbox" checked={facts.hechosRelacion?.includes(value as NonNullable<PublicSafetyFacts["hechosRelacion"]>[number]) ?? false} onChange={() => toggleRelationEvent(value as NonNullable<PublicSafetyFacts["hechosRelacion"]>[number])} /> {label}</label>)}</fieldset>
      <ToggleQuestion legend="¿Se refieren episodios anteriores de violencia física o psíquica?" value={facts.episodiosPrevios} onChange={(value) => set("episodiosPrevios", value)} />
    </>}
    {concept.id === "agresiones_lesiones" && <>
      <ToggleQuestion legend="¿Ha existido golpe o agresión física?" value={facts.agresionFisica} onChange={(value) => set("agresionFisica", value)} />
      {facts.agresionFisica && <><ToggleQuestion legend="¿Existe o se refiere alguna lesión?" value={facts.lesion} onChange={(value) => set("lesion", value)} />
        {facts.lesion && <ChoiceQuestion legend="¿Se conoce el resultado asistencial?" value={facts.resultadoAsistencial} options={medicalResultOptions} onChange={(value) => set("resultadoAsistencial", value as PublicSafetyFacts["resultadoAsistencial"])} />}
        <ToggleQuestion legend="¿Se utilizó arma, botella, objeto o medio especialmente peligroso?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} />
        <ToggleQuestion legend="¿Existe un resultado aparentemente de especial gravedad?" value={facts.resultadoEspecialGravedad} onChange={(value) => set("resultadoEspecialGravedad", value)} />
        <ToggleQuestion legend="¿Hay indicios de que la conducta pudiera estar dirigida a matar?" value={facts.indiciosFinalidadMatar} onChange={(value) => set("indiciosFinalidadMatar", value)} />
        {facts.indiciosFinalidadMatar && <div className="sp-question-help">Recoge zona corporal atacada, medio, número e intensidad de acciones, estrangulamiento o disparos, expresiones, conducta y motivo por el que cesó.</div>}
        <ToggleQuestion legend="¿La agresión se produjo en un contexto sexual?" value={facts.contextoSexual} onChange={(value) => set("contextoSexual", value)} />
      </>}
    </>}
    {concept.id === "agresiones_sexuales" && <>
      <ToggleQuestion legend="¿Se refiere un acto de contenido sexual no consentido?" value={facts.actoSexualNoConsentido} onChange={(value) => set("actoSexualNoConsentido", value)} />
      {facts.actoSexualNoConsentido && <><ToggleQuestion legend="¿La víctima es menor de 16 años?" value={facts.menorDieciseis} onChange={(value) => set("menorDieciseis", value)} />
        <ToggleQuestion legend="¿El presunto autor tiene 18 años o más?" value={facts.autorMayorEdad} onChange={(value) => set("autorMayorEdad", value)} />
        {facts.menorDieciseis && <ChoiceQuestion legend="¿Qué conducta se refiere?" value={facts.conductaSexual} options={sexualConductOptions} onChange={(value) => set("conductaSexual", value as PublicSafetyFacts["conductaSexual"])} />}
        {(facts.conductaSexual === undefined || facts.conductaSexual === "acto_fisico") && <><ChoiceQuestion legend="¿Qué consta sobre el consentimiento?" value={facts.estadoConsentimiento} options={consentOptions} onChange={(value) => set("estadoConsentimiento", value as PublicSafetyFacts["estadoConsentimiento"])} />
          <ToggleQuestion legend="¿Hubo acceso carnal o introducción vaginal o anal de miembros corporales u objetos?" value={facts.penetracion} onChange={(value) => set("penetracion", value)} />
          <ToggleQuestion legend="¿Existió violencia o intimidación?" value={facts.violenciaIntimidacion} onChange={(value) => set("violenciaIntimidacion", value)} />
          <ToggleQuestion legend="¿La voluntad estaba anulada por cualquier causa?" value={facts.voluntadAnulada} onChange={(value) => set("voluntadAnulada", value)} />
          <ToggleQuestion legend="¿Intervinieron dos o más personas?" value={facts.variasPersonas} onChange={(value) => set("variasPersonas", value)} />
          <ToggleQuestion legend="¿Hubo violencia extrema o actos especialmente degradantes o vejatorios?" value={facts.violenciaExtremaDegradante} onChange={(value) => set("violenciaExtremaDegradante", value)} />
          <ToggleQuestion legend="¿Consta especial vulnerabilidad por edad, enfermedad, discapacidad u otra circunstancia?" value={facts.vulnerabilidadEspecial} onChange={(value) => set("vulnerabilidadEspecial", value)} />
          <ToggleQuestion legend="¿Se administraron fármacos, drogas u otra sustancia para anular la voluntad?" value={facts.sustanciasAdministradas} onChange={(value) => set("sustanciasAdministradas", value)} />
          {facts.menorDieciseis && <><ToggleQuestion legend="¿Intervino una organización o grupo criminal?" value={facts.organizacionCriminal} onChange={(value) => set("organizacionCriminal", value)} /><ToggleQuestion legend="¿Podría depender de la excepción del art. 183 bis?" value={facts.posibleExcepcion183Bis} onChange={(value) => set("posibleExcepcion183Bis", value)} /></>}
        </>}
        <ToggleQuestion legend="¿Existe posible sumisión o vulnerabilidad química?" value={facts.posibleSumisionQuimica} onChange={(value) => set("posibleSumisionQuimica", value)} />
        {facts.posibleSumisionQuimica && <div className="sp-question-help">Pérdida de memoria, somnolencia intensa, desorientación, pérdida de conciencia no explicada, sospecha de sustancias o aprovechamiento de intoxicación.</div>}
        <ToggleQuestion legend="¿Existen lesiones?" value={facts.lesion} onChange={(value) => set("lesion", value)} />
        <ToggleQuestion legend="¿Existen amenazas o coacciones autónomas y adicionales?" value={facts.amenazasAutonomas} onChange={(value) => set("amenazasAutonomas", value)} />
        <ToggleQuestion legend="¿Hay arma u objeto peligroso?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} />
        <ToggleQuestion legend="¿Han transcurrido más de 72 horas?" value={facts.tiempoTranscurridoSuperior72h} onChange={(value) => set("tiempoTranscurridoSuperior72h", value)} />
      </>}
    </>}
    {concept.id === "peleas_rinas" && <>
      <ChoiceQuestion legend="¿Cómo se desarrolla el enfrentamiento?" value={facts.tipoRina} options={fightTypeOptions} onChange={(value) => set("tipoRina", value as PublicSafetyFacts["tipoRina"])} />
      {facts.tipoRina && <><ToggleQuestion legend="¿Se utilizan botellas, cuchillos, palos u otros instrumentos peligrosos?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} />
        <ToggleQuestion legend="¿Hay personas lesionadas?" value={facts.lesion} onChange={(value) => set("lesion", value)} />
        {facts.lesion && <ToggleQuestion legend="¿Puede identificarse quién causó una lesión concreta?" value={facts.lesionIndividualizable} onChange={(value) => set("lesionIndividualizable", value)} />}
        <ToggleQuestion legend="¿La víctima es agente?" value={facts.victimaAgente} onChange={(value) => set("victimaAgente", value)} />
      </>}
    </>}
    {concept.id === "amenazas_coacciones" && <>
      <ChoiceQuestion legend="¿Qué está haciendo la persona?" value={facts.conductaLibertad} options={freedomConductOptions} onChange={(value) => set("conductaLibertad", value as PublicSafetyFacts["conductaLibertad"])} />
      {facts.conductaLibertad === "amenaza" && <><ChoiceQuestion legend="¿Qué mal anuncia?" value={facts.malAnunciado} options={threatHarmOptions} onChange={(value) => set("malAnunciado", value as PublicSafetyFacts["malAnunciado"])} />
        <ToggleQuestion legend="¿Exige algo o impone alguna condición?" value={facts.condicionImpuesta} onChange={(value) => set("condicionImpuesta", value)} />
      </>}
      {facts.conductaLibertad === "coaccion" && <ChoiceQuestion legend="¿Cómo impone o impide la conducta?" value={facts.coaccionEntidad} options={coactionOptions} onChange={(value) => set("coaccionEntidad", value as PublicSafetyFacts["coaccionEntidad"])} />}
      {facts.conductaLibertad && facts.conductaLibertad !== "acoso" && <><ToggleQuestion legend="¿Utiliza o exhibe arma u objeto peligroso?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} />
        <ToggleQuestion legend="¿Hay mensajes, audios, llamadas u otros soportes?" value={facts.soportes} onChange={(value) => set("soportes", value)} />
      </>}
    </>}
    {showComplaintQuestion && <><ChoiceQuestion legend="Procedibilidad del delito sexual" value={facts.procedibilidadSexual} options={procedureOptions} onChange={(value) => { set("procedibilidadSexual", value as PublicSafetyFacts["procedibilidadSexual"]); set("noDeseaDenunciar", value === "pendiente"); }} />
      <div className="sp-question-help">La denuncia puede ser oral y documentarse después. Si está pendiente, continúan protección, asistencia, diligencias urgentes, preservación de indicios y coordinación.</div>
    </>}
    {needsProcessualFacts && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} minor={fixedMinorOffence} />}
    <IncidentResolvedOutcome result={result} onNavigate={onNavigate} showProcessual={showResolvedProcessual} />
  </>;
}

function RelationshipQuestion({ facts, set, askSexes = true }: { facts: PublicSafetyFacts; set: <K extends keyof PublicSafetyFacts>(key: K, value: PublicSafetyFacts[K]) => void; askSexes?: boolean }) {
  return <>
    <ChoiceQuestion legend="¿Qué relación existe entre autor y víctima?" value={facts.tipoRelacion} options={relationshipOptions} onChange={(value) => set("tipoRelacion", value as PublicSafetyFacts["tipoRelacion"])} />
    {facts.tipoRelacion && <>{askSexes && <><ChoiceQuestion legend="Sexo del presunto autor cuando resulte jurídicamente relevante" value={facts.sexoAutor} options={sexOptions} onChange={(value) => set("sexoAutor", value as PublicSafetyFacts["sexoAutor"])} /><ChoiceQuestion legend="Sexo de la víctima cuando resulte jurídicamente relevante" value={facts.sexoVictima} options={sexOptions} onChange={(value) => set("sexoVictima", value as PublicSafetyFacts["sexoVictima"])} /></>}<ToggleQuestion legend="¿Conviven actualmente? Es un dato separado y no decide por sí solo VioGén." value={facts.convivencia} onChange={(value) => set("convivencia", value)} /></>}
  </>;
}

function ChoiceQuestion({ legend, value, options, onChange }: { legend: string; value: string | undefined; options: Array<[string, string]>; onChange: (value: string) => void }) { return <fieldset className="sp-choice"><legend>{legend}</legend>{options.map(([id, label]) => <label key={id}><input type="radio" checked={value === id} onChange={() => onChange(id)} /> {label}</label>)}</fieldset>; }
function ToggleQuestion({ legend, value, onChange }: { legend: string; value: boolean | undefined; onChange: (value: boolean) => void }) { return <fieldset className="sp-choice"><legend>{legend}</legend><label><input type="radio" checked={value === true} onChange={() => onChange(true)} /> Sí</label><label><input type="radio" checked={value === false} onChange={() => onChange(false)} /> No</label></fieldset>; }

function IncidentResolvedOutcome({ result, onNavigate, showProcessual }: { result: PublicSafetyOutcome; onNavigate: (id: string) => void; showProcessual: boolean }) {
  const attentions = result.resultados.filter(isIncidentAttention);
  const outcomes = result.resultados.filter((item) => !isIncidentAttention(item));
  const actions = uniqueItems(outcomes.flatMap((item) => item.actuacion).filter((item) => !isContinuationAction(item) && !isAttentionAction(item)));
  const attentionItems = uniqueItems([...attentions.map((item) => `${item.titulo}: ${item.texto}`), ...outcomes.flatMap((item) => item.actuacion).filter(isAttentionAction)]);
  return <>{outcomes.map((item, index) => <div key={`${item.titulo}-${index}`} className={item.destacado ? `sp-incident-${item.destacado}` : undefined}><ResultCard title={item.titulo} norma={item.norma} clasificacion={item.clasificacion} text={item.texto} showText={needsOutcomeDetail(item.titulo)} /></div>)}
    {result.procedibilidad && <section className={`sp-section sp-procedure ${result.procedibilidad.estado.startsWith("PENDIENTE") ? "pending" : "complete"}`}><h3>PROCEDIBILIDAD</h3><strong>{result.procedibilidad.estado}</strong><p>{result.procedibilidad.fundamento}</p></section>}
    {result.procesal && showProcessual ? <><AuthorSituation decision={result.procesal} /><Continuation decision={result.procesal} additionalItems={actions} /></> : <OperationalSection title="Actuación inmediata" items={actions} />}
    <OperationalSection title="Atención" items={attentionItems} />
    {result.conexiones.length > 0 && <section className="sp-section"><h3>Conexiones activas</h3><div className="sp-connections">{result.conexiones.map((item) => item.conceptId ? <button key={`${item.conceptId}-${item.etiqueta}`} onClick={() => onNavigate(item.conceptId)}><strong>{item.etiqueta}</strong><small>{item.motivo}</small><b>›</b></button> : <div key={item.etiqueta}><strong>{item.etiqueta}</strong><small>{item.motivo}</small></div>)}</div></section>}
    <LegalFoundation normas={uniqueItems(result.resultados.map((item) => item.norma))} />
  </>;
}

function WeaponDecision({ concept, facts }: { concept: PublicConcept; facts: PublicSafetyFacts }) {
  const ordinaryObject = concept.id === "objetos_peligrosos";
  const [tipo, setTipo] = useState<WeaponObjectInput["tipo"]>("navaja");
  const [mecanismo, setMecanismo] = useState<"automatico" | "no_automatico" | "dudoso">("dudoso");
  const [longitudNavaja, setLongitudNavaja] = useState<"supera_11" | "no_supera_11" | "dudosa">("dudosa");
  const [menorOnce, setMenorOnce] = useState(false); const [dosFilos, setDosFilos] = useState(false); const [puntiaguda, setPuntiaguda] = useState(false);
  const [armamento, setArmamento] = useState<"aprobado" | "imitacion" | "no" | "dudoso">("dudoso");
  const [circunstanciaTenencia, setCircunstanciaTenencia] = useState<"ninguna" | "contemplacion" | "reparacion" | "transmision">("ninguna");
  const [disponibilidad, setDisponibilidad] = useState<"encima" | "efectos" | "accesible" | "vehiculo" | "sin_disponente">("efectos"); const [comportamiento, setComportamiento] = useState<WeaponConduct>(facts.medioPeligroso ? "usa" : "porte"); const [contexto, setContexto] = useState<"sin_incidente" | "altercado" | "violento" | "amenazas" | "otro_delito" | "otras">("sin_incidente"); const [flagrante, setFlagrante] = useState<boolean>(); const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const [motivo, setMotivo] = useState<WeaponContextInput["motivo"]>();
  const [transporte, setTransporte] = useState<WeaponContextInput["transporte"]>();
  const [lugar, setLugar] = useState<WeaponContextInput["lugar"]>();
  const [momento, setMomento] = useState<WeaponContextInput["momento"]>();
  const [consumo, setConsumo] = useState<WeaponContextInput["consumo"]>();
  const [accesoRestringido, setAccesoRestringido] = useState<WeaponContextInput["accesoRestringido"]>();
  const [motivoSeguridadFinalizado, setMotivoSeguridadFinalizado] = useState<WeaponContextInput["motivoSeguridadFinalizado"]>();
  const processual = processualInput(flagrante, processFacts);
  const processualAnswered = hasProcessualAnswer(flagrante, processFacts);
  const clearCarry = () => { setCircunstanciaTenencia("ninguna"); setMotivo(undefined); setTransporte(undefined); setLugar(undefined); setMomento(undefined); setConsumo(undefined); setAccesoRestringido(undefined); setMotivoSeguridadFinalizado(undefined); };
  const chooseBehaviour = (value: WeaponConduct) => { setComportamiento(value); if (value !== "porte") clearCarry(); if (value === "exhibe" && contexto === "sin_incidente") setContexto("altercado"); };
  const chooseTipo = (value: WeaponObjectInput["tipo"]) => { setTipo(value); setMecanismo("dudoso"); setLongitudNavaja("dudosa"); setMenorOnce(false); setDosFilos(false); setPuntiaguda(false); setArmamento("dudoso"); clearCarry(); };
  const chooseMechanism = (value: typeof mecanismo) => { setMecanismo(value); setLongitudNavaja("dudosa"); if (value === "automatico") clearCarry(); };
  const choosePlace = (value: NonNullable<WeaponContextInput["lugar"]>) => { setLugar(value); if (!["establecimiento", "ocio", "reunion"].includes(value)) { setMomento(undefined); setConsumo(undefined); } setAccesoRestringido(undefined); setMotivoSeguridadFinalizado(undefined); };
  const showAvailability = ordinaryObject && comportamiento === "porte";
  const showContext = comportamiento === "manipula" || comportamiento === "exhibe";
  const showTenenciaExcepcional = !ordinaryObject && comportamiento === "porte";
  const prohibitedTechnical = mecanismo === "automatico" && tipo === "navaja" || tipo === "hoja" && menorOnce && dosFilos && puntiaguda;
  const showCarry = !ordinaryObject && comportamiento === "porte" && !prohibitedTechnical;
  const sensitivePlace = lugar === "establecimiento" || lugar === "ocio" || lugar === "reunion";
  const legitimatePurpose = motivo === "trabajo" || motivo === "actividad" || motivo === "trayecto";
  const protectedTransport = transporte === "funda" || transporte === "equipamiento";
  const coherentPlace = lugar === "trayecto" || motivo === "trabajo" && lugar === "trabajo" || motivo === "actividad" && lugar === "actividad";
  const showSafetyAccess = showCarry && legitimatePurpose && protectedTransport && coherentPlace && consumo !== "si";
  const contextOptions = comportamiento === "exhibe" ? weaponRelatedContext : weaponContext;
  const inferredAvailability = ordinaryObject ? disponibilidad : transporte === "bolsillo" || transporte === "accesible" ? "accesible" : "efectos";
  const result = { ...resolveWeaponOutcome({ tipo: ordinaryObject ? "objeto" : tipo, mecanismo, longitudNavaja, hojaMenorOnce: menorOnce, dosFilos, puntiaguda, armamento, supuestoEspecifico: circunstanciaTenencia !== "ninguna", circunstanciaTenencia: circunstanciaTenencia === "ninguna" ? undefined : circunstanciaTenencia }, { disponibilidad: inferredAvailability, comportamiento, contexto: showContext ? contexto : undefined, motivo, transporte, lugar, momento, consumo, accesoRestringido: showSafetyAccess ? accesoRestringido : undefined, motivoSeguridadFinalizado: showSafetyAccess && accesoRestringido === "si" ? motivoSeguridadFinalizado : undefined, ...processual }), processualAnswered };
  return <>{facts.medioPeligroso && <div className="sp-highlight neutral"><strong>MEDIO PELIGROSO YA REGISTRADO</strong><p>Se conserva como hecho de la intervención. Completa solo las características del objeto necesarias para su descripción.</p></div>}<OperationalSection title="Qué comprobar" items={concept.comprobar} />{facts.medioPeligroso ? <div className="sp-question-help">La conducta contra una persona ya consta en la intervención; completa únicamente la identificación del objeto.</div> : <fieldset className="sp-choice"><legend>¿Qué ocurre con el objeto?</legend>{weaponBehaviour.map(([id, label]) => <label key={id}><input type="radio" checked={comportamiento === id} onChange={() => chooseBehaviour(id as WeaponConduct)} /> {label}</label>)}</fieldset>}{showAvailability && <fieldset className="sp-choice"><legend>¿Dónde se encuentra?</legend>{weaponAvailability.map(([id, label]) => <label key={id}><input type="radio" checked={disponibilidad === id} onChange={() => setDisponibilidad(id as typeof disponibilidad)} /> {label}</label>)}</fieldset>}{showContext && <fieldset className="sp-choice"><legend>¿Qué situación se observa?</legend>{contextOptions.map(([id, label]) => <label key={id}><input type="radio" checked={contexto === id} onChange={() => setContexto(id as typeof contexto)} /> {label}</label>)}</fieldset>}{ordinaryObject ? <div className="sp-highlight neutral"><strong>OBJETO ORDINARIO</strong><ul><li>Solo porte: no implica infracción automática.</li><li>Intimidación o agresión: analizar primero vía penal.</li><li>El uso puede ser relevante aunque el objeto no sea arma.</li></ul></div> : <><fieldset className="sp-choice"><legend>¿Qué tipo de arma blanca se observa?</legend>{bladeTypes.map(([id, label]) => <label key={id}><input type="radio" checked={tipo === id} onChange={() => chooseTipo(id as WeaponObjectInput["tipo"])} /> {label}</label>)}</fieldset>{tipo === "navaja" && <fieldset className="sp-choice"><legend>¿Cómo es el mecanismo de apertura?</legend><p className="sp-question-help">Indica si el mecanismo es automático.</p>{mechanismOptions.map(([id, label]) => <label key={id}><input type="radio" checked={mecanismo === id} onChange={() => chooseMechanism(id as typeof mecanismo)} /> {label}</label>)}{mecanismo === "no_automatico" && <div className="sp-nested-question"><strong>Longitud desde el reborde o tope del mango hasta el extremo</strong>{manualLengthOptions.map(([id, label]) => <label key={id}><input type="radio" checked={longitudNavaja === id} onChange={() => setLongitudNavaja(id as typeof longitudNavaja)} /> {label}</label>)}</div>}</fieldset>}{tipo === "hoja" && <fieldset className="sp-choice"><legend>¿Reúne las tres características de un puñal?</legend><label><input type="checkbox" checked={menorOnce} onChange={(event) => setMenorOnce(event.target.checked)} /> Hoja menor de 11 cm</label><label><input type="checkbox" checked={dosFilos} onChange={(event) => setDosFilos(event.target.checked)} /> Dos filos</label><label><input type="checkbox" checked={puntiaguda} onChange={(event) => setPuntiaguda(event.target.checked)} /> Punta</label></fieldset>}{(tipo === "cuchillo" || tipo === "machete") && <fieldset className="sp-choice"><legend>¿Forma parte de un armamento debidamente aprobado?</legend>{armamentOptions.map(([id, label]) => <label key={id}><input type="radio" checked={armamento === id} onChange={() => setArmamento(id as typeof armamento)} /> {label}</label>)}</fieldset>}{showTenenciaExcepcional && <fieldset className="sp-choice"><legend>¿Existe una circunstancia excepcional de tenencia?</legend>{exceptionalTenureOptions.map(([id, label]) => <label key={id}><input type="radio" checked={circunstanciaTenencia === id} onChange={() => setCircunstanciaTenencia(id as typeof circunstanciaTenencia)} /> {label}</label>)}</fieldset>}{showCarry && <><fieldset className="sp-choice"><legend>¿Para qué lleva el objeto?</legend>{carryPurposeOptions.map(([id, label]) => <label key={id}><input type="radio" checked={motivo === id} onChange={() => { setMotivo(id as NonNullable<typeof motivo>); setAccesoRestringido(undefined); setMotivoSeguridadFinalizado(undefined); }} /> {label}</label>)}</fieldset><fieldset className="sp-choice"><legend>¿Cómo lo transporta?</legend>{carryTransportOptions.map(([id, label]) => <label key={id}><input type="radio" checked={transporte === id} onChange={() => { setTransporte(id as NonNullable<typeof transporte>); setAccesoRestringido(undefined); setMotivoSeguridadFinalizado(undefined); }} /> {label}</label>)}</fieldset><fieldset className="sp-choice"><legend>¿Dónde se encuentra?</legend>{carryPlaceOptions.map(([id, label]) => <label key={id}><input type="radio" checked={lugar === id} onChange={() => choosePlace(id as NonNullable<typeof lugar>)} /> {label}</label>)}</fieldset>{sensitivePlace && <fieldset className="sp-choice"><legend>Datos adicionales relevantes</legend>{momentOptions.map(([id, label]) => <label key={id}><input type="radio" checked={momento === id} onChange={() => setMomento(id as NonNullable<typeof momento>)} /> {label}</label>)}<span className="sp-choice-divider">¿Se observan signos de consumo o influencia?</span>{yesNoUnknown.map(([id, label]) => <label key={`consumo-${id}`}><input type="radio" checked={consumo === id} onChange={() => setConsumo(id as NonNullable<typeof consumo>)} /> {label}</label>)}</fieldset>}{showSafetyAccess && <fieldset className="sp-choice"><legend>¿Intenta acceder a un espacio con una restricción concreta de seguridad?</legend>{yesNoUnknown.map(([id, label]) => <label key={`acceso-${id}`}><input type="radio" checked={accesoRestringido === id} onChange={() => { setAccesoRestringido(id as NonNullable<typeof accesoRestringido>); if (id !== "si") setMotivoSeguridadFinalizado(undefined); }} /> {label}</label>)}{accesoRestringido === "si" && <div className="sp-nested-question"><strong>¿Ha desaparecido el motivo concreto de seguridad?</strong>{yesNoUnknown.map(([id, label]) => <label key={`fin-${id}`}><input type="radio" checked={motivoSeguridadFinalizado === id} onChange={() => setMotivoSeguridadFinalizado(id as NonNullable<typeof motivoSeguridadFinalizado>)} /> {label}</label>)}</div>}</fieldset>}</>}</>}<div className="sp-dimensions"><p><span>CLASIFICACIÓN DEL OBJETO</span><strong>{result.clasificacionObjeto}</strong></p><p><span>CONDUCTA OBSERVADA</span><strong>{result.conducta}</strong></p></div>{result.kind === "penal" && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} />}<ResolvedOutcome result={result} weapon={ordinaryObject ? "object" : "weapon"} showFoundation={false} /><WeaponDetails concept={concept} result={result} ordinaryObject={ordinaryObject} /></>;
}

function WeaponDetails({ concept, result, ordinaryObject }: { concept: PublicConcept; result: WeaponOutcome; ordinaryObject: boolean }) { return <div className="sp-common">{result.salidaSubsidiaria && <CollapsibleSection title="Salida administrativa subsidiaria"><p>{result.salidaSubsidiaria}</p></CollapsibleSection>}{result.derivaOtroDelito && <CollapsibleSection title={ordinaryObject ? "Posible delito cometido utilizando el objeto" : "Delito cometido utilizando el arma"}><p>{ordinaryObject ? "La clasificación del objeto no elimina su relevancia por el uso ni activa automáticamente el art. 563 CP." : "La vía del art. 563 y el delito cometido utilizando el arma exigen sus propios requisitos."}</p>{result.dependenciaFutura && <p><strong>{result.dependenciaFutura}</strong></p>}</CollapsibleSection>}<CollapsibleSection title="Datos para acta o diligencias"><Checklist items={["Tipo, características y dimensiones relevantes.", "Lugar, motivo y forma de porte.", "Actividad relacionada y accesibilidad.", "Conducta y contexto observados.", "Fotografías, cuando proceda."]} /></CollapsibleSection><CollapsibleSection title="Fundamento jurídico">{concept.detalle?.length ? <Checklist items={concept.detalle} /> : null}{!ordinaryObject && <p>El art. 563 exige conjuntamente los requisitos constitucionales ya incorporados al motor.</p>}<Checklist items={concept.fuentes ?? []} /></CollapsibleSection></div> }

function AuthorityDecision({ concept }: { concept: PublicConcept }) {
  const options = concept.id === "desobediencia" ? [["admin", "Desobediencia administrativa: falta alguno de los requisitos penales"], ["penal", "Desobediencia grave: concurren todos los requisitos penales"]] : concept.id === "resistencia" ? [["admin", "Resistencia pasiva leve, oposición de escasa entidad o dificultad menor"], ["penal", "Resistencia pasiva grave o activa de entidad penal sin atentado"], ["atentado", "Agresión, acometimiento o resistencia grave mediante violencia o intimidación grave"]] : [["admin", "Expresión ofensiva sin anuncio serio de mal penal"], ["leve", "Amenaza leve"], ["art169", "Amenaza con entidad del art. 169 CP"], ["atentado", "Intimidación grave integrada en resistencia grave o inicio inmediato de ataque"]];
  const [level, setLevel] = useState(options[0][0]); const [flagrante, setFlagrante] = useState<boolean>(); const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const penal = ["penal", "atentado", "art169"].includes(level);
  const processual = processualInput(flagrante, processFacts);
  const processualAnswered = hasProcessualAnswer(flagrante, processFacts);
  const result = resolveAuthorityOutcome(concept.id, level, processual);
  return <><OperationalSection title="Indicadores objetivos" items={concept.comprobar} /><fieldset className="sp-choice"><legend>Selecciona la conducta observada ya comprobada</legend>{options.map(([id, label]) => <label key={id}><input type="radio" checked={level === id} onChange={() => setLevel(id)} /> {label}</label>)}</fieldset>{penal && level !== "leve" && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} />}{result && <ResolvedOutcome result={result} showProcessual={!penal || processualAnswered} />}</>;
}

function PatrimonyDecision({ facts, setFacts, onNavigate }: { facts: PublicSafetyFacts; setFacts: Dispatch<SetStateAction<PublicSafetyFacts>>; onNavigate: (id: string) => void }) {
  const [patrimony, setPatrimony] = useState<PatrimonyFacts>({});
  const [flagrante, setFlagrante] = useState<boolean>();
  const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const set = <K extends keyof PatrimonyFacts>(key: K, value: PatrimonyFacts[K]) => setPatrimony((current) => ({ ...current, [key]: value }));
  const setRelation = <K extends keyof PublicSafetyFacts>(key: K, value: PublicSafetyFacts[K]) => setFacts((current) => ({ ...current, [key]: value }));
  const outcome = resolvePatrimonyOutcome(patrimony, processualInput(flagrante, processFacts), facts);
  const minor = outcome.gravedad === "DELITO LEVE";
  const showProcess = Boolean(outcome.procesal) && hasProcessualAnswer(flagrante, processFacts, minor);
  const mainOptions: Array<[NonNullable<PatrimonyFacts["hechoPrincipal"]>, string]> = [["apoderamiento", "Se llevan o intentan llevar una cosa"], ["recepcion", "La cosa se recibió legítimamente y después no se devuelve o se dispone de ella"], ["danos", "Se daña o destruye una cosa"], ["no_claro", "No puede determinarse todavía"]];
  const eventChange = (value: NonNullable<PatrimonyFacts["hechoPrincipal"]>) => { setPatrimony({ hechoPrincipal: value }); setFlagrante(undefined); setProcessFacts({}); };
  const yesNo = (legend: string, key: keyof PatrimonyFacts) => <ToggleQuestion legend={legend} value={patrimony[key] as boolean | undefined} onChange={(value) => set(key, value as never)} />;
  return <>
    <fieldset className="sp-choice"><legend>¿Cuál es el hecho principal observado?</legend>{mainOptions.map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.hechoPrincipal === value} onChange={() => eventChange(value)} /> {label}</label>)}</fieldset>
    {patrimony.hechoPrincipal && patrimony.hechoPrincipal !== "no_claro" && <>
      <RelationshipQuestion facts={facts} set={setRelation} askSexes={false} />
      {facts.tipoRelacion === "esposa" && <>{yesNo("¿Existe separación legal o de hecho?", "separacionConyugal")}{patrimony.separacionConyugal === false && yesNo("¿Existe proceso judicial de separación, divorcio o nulidad?", "procesoSeparacionDivorcioNulidad")}</>}
      {facts.tipoRelacion === "familiar" && <><fieldset className="sp-choice"><legend>Vínculo familiar a efectos del art. 268 CP</legend>{[["ascendiente", "Ascendiente"], ["descendiente", "Descendiente"], ["hermano", "Hermano/a"], ["afin_primer_grado", "Afín en primer grado"], ["otro", "Otro vínculo"], ["no_determinado", "No determinado"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.vinculoFamiliar268 === value} onChange={() => set("vinculoFamiliar268", value as PatrimonyFacts["vinculoFamiliar268"])} /> {label}</label>)}</fieldset>{patrimony.vinculoFamiliar268 === "afin_primer_grado" && yesNo("¿Conviven?", "afinPrimerGradoConvive")}</>}
      {["esposa", "familiar"].includes(facts.tipoRelacion ?? "") && <>{yesNo("¿Concurre abuso de vulnerabilidad por edad o discapacidad?", "abusoVulnerabilidadEdadDiscapacidad")}{yesNo("¿Participa un tercero extraño?", "terceroExtranoParticipa")}</>}
      <fieldset className="sp-choice"><legend>Titularidad de la cosa</legend>{[["ajena", "Ajena"], ["propia", "Propia"], ["compartida", "Compartida"], ["no_determinada", "No determinada"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.titularidad === value} onChange={() => set("titularidad", value as PatrimonyFacts["titularidad"])} /> {label}</label>)}</fieldset>
    </>}
    {patrimony.hechoPrincipal === "apoderamiento" && patrimony.titularidad === "ajena" && <>
      {yesNo("¿Existe intención de apropiación o beneficio?", "intencionApropiacionBeneficio")}
      {patrimony.intencionApropiacionBeneficio === true && yesNo("¿Se actúa sin consentimiento del titular?", "sinConsentimiento")}
      {patrimony.sinConsentimiento === true && <ToggleQuestion legend="¿Hay violencia física?" value={patrimony.violenciaFisica} onChange={(value) => set("violenciaFisica", value)} />}
      {patrimony.violenciaFisica !== undefined && <ToggleQuestion legend="¿Hay intimidación?" value={patrimony.intimidacion} onChange={(value) => set("intimidacion", value)} />}
      {patrimony.violenciaFisica !== undefined && patrimony.intimidacion !== undefined && ((patrimony.violenciaFisica || patrimony.intimidacion) ? <><fieldset className="sp-choice"><legend>Momento de la violencia o intimidación</legend>{[["apoderamiento", "Para obtener la cosa"], ["conservar", "Para conservarla"], ["huida", "Durante la huida"], ["auxiliador", "Contra quien auxilia"], ["perseguidor", "Contra quien persigue"], ["no_determinado", "No determinado"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.momentoViolencia === value} onChange={() => set("momentoViolencia", value as PatrimonyFacts["momentoViolencia"])} /> {label}</label>)}</fieldset>{patrimony.momentoViolencia && yesNo("¿Está conectada con obtener o conservar la cosa, huir o vencer a quien auxilia o persigue?", "conexionViolenciaApoderamiento")}{patrimony.conexionViolenciaApoderamiento === true && <>{yesNo("¿Hay arma o medio peligroso presente?", "armaPresente")}{patrimony.armaPresente && yesNo("¿Se usa efectivamente el arma o medio peligroso?", "armaUsada")}{yesNo("¿Existe lesión autónoma?", "lesionAutonoma")}{yesNo("¿Existe amenaza o coacción autónoma?", "amenazaCoaccionAutonoma")}</>}</> : <fieldset className="sp-choice"><legend>Fuerza material para acceder o abandonar</legend>{[["ninguna", "Ninguna"], ["escalamiento", "Escalamiento acreditado"], ["rotura_acceso", "Rotura de acceso"], ["fractura_contenedor", "Fractura de mueble o recipiente"], ["cerradura_claves", "Forzamiento de cerradura o claves"], ["llave_falsa", "Llave falsa"], ["alarma_acceso_salida", "Inutilización de alarma de acceso o salida"], ["llave_entregada_legitima", "Llave entregada legítimamente"], ["escalamiento_dudoso", "Escalamiento dudoso"], ["no_determinada", "No determinada"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.fuerza === value} onChange={() => set("fuerza", value as PatrimonyFacts["fuerza"])} /> {label}</label>)}</fieldset>)}
      {patrimony.fuerza && patrimony.fuerza !== "ninguna" && <fieldset className="sp-choice"><legend>Lugar</legend>{[["morada", "Morada, aunque esté temporalmente vacía"], ["local_abierto", "Local abierto al público"], ["local_fuera_horario", "Local fuera del horario de apertura"], ["dependencia", "Dependencia de casa o local"], ["otro", "Otro lugar"], ["no_determinado", "No determinado"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.tipoLugar === value} onChange={() => set("tipoLugar", value as PatrimonyFacts["tipoLugar"])} /> {label}</label>)}</fieldset>}
      {(patrimony.fuerza === "ninguna" || patrimony.conexionViolenciaApoderamiento === true) && <><MoneyQuestion facts={patrimony} set={set} />{patrimony.cuantiaAcreditada === true && <>{yesNo("¿Se neutraliza un dispositivo antihurto instalado en la propia cosa?", "dispositivoAntihurtoEnCosaNeutralizado")}{yesNo("¿Es teléfono móvil u otro dispositivo del art. 235.1.10 CP?", "telefonoODispositivo235")}{patrimony.telefonoODispositivo235 && yesNo("¿Es una existencia destinada a venta, almacenamiento o exposición comercial?", "existenciaComercialVentaAlmacenExposicion")}</>}</>}
    </>}
    {patrimony.hechoPrincipal === "recepcion" && patrimony.titularidad === "ajena" && <>
      <fieldset className="sp-choice"><legend>¿Cómo llegó la cosa a poder del autor?</legend>{[["autor_entrega_legitima", "Entrega legítima"], ["autor_acceso_material", "Mero acceso material o laboral"], ["autor_facultades_administracion", "Con facultades de administración"], ["victima_titular", "Seguía en posesión del titular"], ["tercero", "Por un tercero"], ["no_determinada", "No determinado"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.posesionPrevia === value} onChange={() => set("posesionPrevia", value as PatrimonyFacts["posesionPrevia"])} /> {label}</label>)}</fieldset>
      {patrimony.posesionPrevia && yesNo("¿Hubo engaño previo que provocó el acto de disposición?", "enganoPrevioActoDisposicion")}{patrimony.enganoPrevioActoDisposicion === false && <>{yesNo("¿Existía obligación de devolver o entregar?", "obligacionDevolverEntregar")}{yesNo("¿Tenía facultades de administración?", "facultadesAdministracion")}{patrimony.facultadesAdministracion && yesNo("¿Excedió esas facultades causando perjuicio?", "excesoFacultadesConPerjuicio")}{yesNo("¿Se apropió o negó haber recibido la cosa?", "conductaApropiacionONegacion")}{yesNo("¿Es un supuesto residual fuera del art. 253?", "viaApropiacionFuera253")}{(patrimony.conductaApropiacionONegacion || patrimony.viaApropiacionFuera253 || patrimony.excesoFacultadesConPerjuicio) && <MoneyQuestion facts={patrimony} set={set} />}</>}
    </>}
    {patrimony.hechoPrincipal === "danos" && patrimony.titularidad === "ajena" && <><fieldset className="sp-choice"><legend>Intencionalidad</legend>{[["deliberado", "Daño deliberado"], ["imprudente_accidental", "Imprudente o accidental"], ["no_determinado", "No determinada"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.intencionalidadDano === value} onChange={() => set("intencionalidadDano", value as PatrimonyFacts["intencionalidadDano"])} /> {label}</label>)}</fieldset>{patrimony.intencionalidadDano && yesNo("¿Es un daño informático?", "danoInformatico")}{patrimony.intencionalidadDano === "imprudente_accidental" && yesNo("¿La imprudencia es grave?", "imprudenciaGrave")}{patrimony.danoInformatico === false && <><MoneyQuestion facts={patrimony} set={set} />{patrimony.cuantiaAcreditada === true && <>{yesNo("¿Afecta a bien de dominio o uso público o comunal?", "bienDominioUsoPublicoComunal")}{yesNo("¿Se emplea medio destructivo o se genera peligro para personas?", "medioDestructivoOPeligroPersonas")}</>}</>}</>}
    {patrimony.titularidad === "ajena" && patrimony.hechoPrincipal !== "danos" && <><fieldset className="sp-choice"><legend>Grado de ejecución</legend>{[["consumado", "Consumado"], ["tentativa", "Tentativa: se inició la ejecución y no se consumó"], ["no_determinado", "No determinado"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.gradoEjecucion === value} onChange={() => set("gradoEjecucion", value as PatrimonyFacts["gradoEjecucion"])} /> {label}</label>)}</fieldset>{patrimony.gradoEjecucion && <details className="sp-common"><summary>Información judicial adicional (opcional)</summary><fieldset className="sp-choice"><legend>Estado de condenas anteriores</legend>{[["no_consta_verificacion", "No consta verificación judicial"], ["antecedentes_no_judicialmente_verificados", "Solo constan reseñas, denuncias, detenciones o antecedentes policiales"], ["condenas_ejecutorias_verificadas", "Condenas ejecutorias verificadas y computables"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.estadoCondenasPrevias === value} onChange={() => set("estadoCondenasPrevias", value as PatrimonyFacts["estadoCondenasPrevias"])} /> {label}</label>)}</fieldset>{patrimony.estadoCondenasPrevias === "condenas_ejecutorias_verificadas" && <><label className="sp-subchoice">Número de condenas ejecutorias <input type="number" min="0" value={patrimony.numeroCondenasEjecutorias ?? ""} onChange={(event) => set("numeroCondenasEjecutorias", event.target.value === "" ? undefined : Number(event.target.value))} /></label>{yesNo("¿Son de la misma naturaleza y del mismo título?", "condenasMismaNaturaleza")}{yesNo("¿Hay alguna condena leve computable?", "algunaCondenaLeve")}{yesNo("¿Todas son menos graves o graves?", "todasCondenasMenosGravesOGraves")}{yesNo("¿Existe alguna condena cancelada o cancelable?", "condenasCanceladasOCancelables")}{yesNo("¿Se han verificado positivamente todos los requisitos?", "requisitosCondenasCompletos")}</>}</details>}</>}
    {outcome.estado === "pendiente" ? <div className="sp-highlight neutral"><strong>{outcome.resultado}</strong><p>{outcome.falta}</p></div> : <PatrimonyOutcomeView outcome={outcome} showProcess={showProcess} onNavigate={onNavigate} />}
    {outcome.procesal && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} minor={minor} />}
  </>;
}

function MoneyQuestion({ facts, set }: { facts: PatrimonyFacts; set: <K extends keyof PatrimonyFacts>(key: K, value: PatrimonyFacts[K]) => void }) { return <fieldset className="sp-choice"><legend>Cuantía o perjuicio</legend><label className="sp-subchoice">Importe en euros <input type="number" min="0" step="0.01" value={facts.cuantia ?? ""} onChange={(event) => set("cuantia", event.target.value === "" ? undefined : Number(event.target.value))} /></label><ToggleQuestion legend="¿La cuantía está acreditada?" value={facts.cuantiaAcreditada} onChange={(value) => set("cuantiaAcreditada", value)} /></fieldset> }

function PatrimonyOutcomeView({ outcome, showProcess, onNavigate }: { outcome: PatrimonyOutcome; showProcess: boolean; onNavigate: (id: string) => void }) { return <><ResultCard title={outcome.resultado} norma={outcome.norma ?? "Código Penal"} clasificacion={outcome.gravedad} text={outcome.hecho} />{outcome.grado && <OperationalSection title="Grado de ejecución" items={[outcome.grado]} />}{outcome.exencion && <div className="sp-highlight neutral"><strong>{outcome.exencion.titulo}</strong><p>{outcome.exencion.fundamento}</p></div>}<OperationalSection title="Por qué" items={outcome.porQue} /><OperationalSection title="Avisos" items={outcome.avisos} />{outcome.procesal && showProcess && <><AuthorSituation decision={outcome.procesal} /><Continuation decision={outcome.procesal} additionalItems={outcome.actuacion} /></>}{outcome.procesal && !showProcess && <OperationalSection title="Actuación inmediata" items={outcome.actuacion} />}{outcome.conexiones.length > 0 && <section className="sp-section"><h3>Conexiones</h3><div className="sp-connections">{outcome.conexiones.map((connection) => <button key={connection.conceptId} onClick={() => onNavigate(connection.conceptId)}><strong>{connection.etiqueta}</strong><small>{connection.motivo}</small><b>›</b></button>)}</div></section>}<LegalFoundation normas={[outcome.norma ?? "Código Penal"]} detalle="Calificación orientativa basada solo en los hechos marcados; documenta los extremos pendientes." /></>; }

function ResolvedOutcome({ result, drug = false, weapon, showFoundation = true, showProcessual }: { result: AuthorityOutcome | DrugOutcome | WeaponOutcome; drug?: boolean; weapon?: "weapon" | "object"; showFoundation?: boolean; showProcessual?: boolean }) {
  const hasProcessualOutput = Boolean(result.situacion || result.detencion);
  const visibleProcessual = showProcessual ?? (!("processualAnswered" in result) || Boolean(result.processualAnswered));
  const relevantObject = weapon === "object" && "kind" in result && !["sin_conclusion_automatica", "valoracion_especifica"].includes(result.kind);
  const actions = result.actuacion.filter((item) => !isContinuationAction(item));
  return <><ResultCard title={result.titulo} norma={result.norma} clasificacion={result.clasificacion} range={"rango" in result ? result.rango : undefined} text={result.porQue} />{hasProcessualOutput && visibleProcessual ? <><AuthorSituation decision={result} /><Continuation decision={result} additionalItems={actions} /></> : <OperationalSection title="Actuación inmediata" items={actions} />}{weapon === "weapon" && "kind" in result && result.kind === "penal" && <EffectsCommon weapon />}{relevantObject && <EffectsCommon object />}{drug && <CommonProcessual showSubstance />}{showFoundation && <LegalFoundation normas={[result.norma]} detalle={"frontera" in result ? result.frontera : "No se usa una cantidad, ni un número de indicios, como frontera automática."} />}</>;
}

function ResultCard({ title, norma, clasificacion, range, text, showText = true }: { title: string; norma: string; clasificacion?: string; range?: string; text: string; showText?: boolean }) { return <section className="sp-result"><span>{title}</span><h3>{norma}</h3>{clasificacion && <strong className={clasificacion.includes("DELITO") ? "sp-pill penal" : "sp-pill"}>{clasificacion}</strong>}{range && <p className="sp-range">Rango legal: <strong>{range}</strong></p>}{showText && <p>{text}</p>}{range && <p>La LO 4/2015 califica esta conducta como infracción grave y prevé una sanción de entre 601 y 30.000 euros. La cuantía concreta será determinada por el órgano sancionador competente.</p>}</section> }
function OperationalSection({ title, items }: { title: string; items: string[] }) { if (!items.length) return null; return <section className="sp-section"><h3>{title}</h3><ul>{items.map((item) => <li key={item}>{item}</li>)}</ul></section> }
function EffectsCommon({ weapon = false, object = false }: { weapon?: boolean; object?: boolean }) { return <CollapsibleSection title={weapon || object ? "Efectos / instrumentos relacionados" : "Efectos / custodia"}><Checklist items={weapon ? ["Arma intervenida, ocupada y custodiada.", "Lugar exacto de intervención y persona que disponía de ella.", "Estado, características y relación objetiva con los hechos."] : object ? ["Objeto asegurado o intervenido cuando proceda por su relación con los hechos.", "Lugar exacto y persona que disponía de él.", "Estado, características y relación objetiva con la conducta."] : seguridadPublica.comunes.efectos} note={weapon || object ? "La intervención y custodia, cuando procedan, se incorporan a las diligencias y a la coordinación con CNP." : seguridadPublica.comunes.efectos_aviso} /></CollapsibleSection> }
function ProcessualControls({ flagrante, setFlagrante, facts, setFacts, minor = false }: { flagrante: boolean | undefined; setFlagrante: (value: boolean) => void; facts: ProcessualFactsForm; setFacts: Dispatch<SetStateAction<ProcessualFactsForm>>; minor?: boolean }) {
  const set = <K extends keyof ProcessualFactsForm>(key: K, value: ProcessualFactsForm[K]) => setFacts((current) => ({ ...current, [key]: value }));
  const chooseFlagrancy = (value: boolean) => { setFlagrante(value); setFacts({}); };
  if (minor) return <fieldset className="sp-choice sp-processual-question"><legend>Hechos del art. 495 LECrim</legend><ToggleQuestion legend="¿Tiene domicilio conocido y verificable?" value={facts.domicilioConocido} onChange={(value) => set("domicilioConocido", value)} />{facts.domicilioConocido === false && <ToggleQuestion legend="¿Presta fianza bastante, cuando resulte exigible?" value={facts.fianzaBastante} onChange={(value) => set("fianzaBastante", value)} />}</fieldset>;
  const allRisks = facts.indiciosHechoSuficientes === true && facts.indiciosParticipacionSuficientes === true;
  return <fieldset className="sp-choice sp-processual-question"><legend>Hechos procesales observados</legend><strong>¿La persona ha sido sorprendida durante la comisión del hecho o inmediatamente después?</strong><label><input type="radio" checked={flagrante === true} onChange={() => chooseFlagrancy(true)} /> Sí</label><label><input type="radio" checked={flagrante === false} onChange={() => chooseFlagrancy(false)} /> No</label>{flagrante === false && <div className="sp-nested-question"><ToggleQuestion legend="¿Existen indicios racionales suficientes de que se ha cometido el hecho delictivo?" value={facts.indiciosHechoSuficientes} onChange={(value) => set("indiciosHechoSuficientes", value)} />{facts.indiciosHechoSuficientes === true && <ToggleQuestion legend="¿Existen indicios racionales suficientes de participación de esta persona?" value={facts.indiciosParticipacionSuficientes} onChange={(value) => set("indiciosParticipacionSuficientes", value)} />}{allRisks && <><p className="sp-question-help">Marca cada circunstancia factual. La ausencia de flagrancia no decide por sí sola la detención.</p><ToggleQuestion legend="¿Ha intentado fugarse o eludir la actuación?" value={facts.intentoFugaElusion} onChange={(value) => set("intentoFugaElusion", value)} /><ToggleQuestion legend="¿La identidad o el domicilio no han podido verificarse?" value={facts.identidadODomicilioNoVerificables} onChange={(value) => set("identidadODomicilioNoVerificables", value)} /><ToggleQuestion legend="¿Existe riesgo concreto de ocultación o destrucción de pruebas?" value={facts.riesgoOcultacionPruebas} onChange={(value) => set("riesgoOcultacionPruebas", value)} /><ToggleQuestion legend="¿Existe riesgo concreto para víctima o testigos?" value={facts.riesgoConcretoVictimaTestigos} onChange={(value) => set("riesgoConcretoVictimaTestigos", value)} /></>}</div>}</fieldset>;
}
function AuthorSituation({ decision }: { decision: { situacion?: string; detencion?: string; escenarioProcesal?: string; fundamentoDetencion?: string } }) { if (!decision.situacion || !decision.detencion) return null; const output = decision.situacion === "DETENIDO" ? "🔴 DETENER" : decision.situacion === "INVESTIGADO NO DETENIDO" ? "🟡 INVESTIGADO NO DETENIDO" : decision.situacion === "NO DETENER TODAVÍA — INVESTIGAR" ? "🟠 NO DETENER TODAVÍA — INVESTIGAR" : decision.situacion; const tone = decision.situacion === "DETENIDO" ? "detain" : decision.situacion === "INVESTIGADO NO DETENIDO" ? "investigate" : "prevent"; return <section className="sp-section sp-processual-output"><h3>SITUACIÓN PROCESAL</h3><div className={`sp-decision-banner ${tone}`}><span aria-hidden="true" /><strong>{output}</strong><small>{decision.detencion === "NO APLICAR MOTOR ADULTO" ? "Motor adulto no aplicable" : `Detención: ${decision.detencion === "SÍ" ? "sí" : "no"}`}</small></div>{decision.fundamentoDetencion && <p className="sp-status-note">{decision.fundamentoDetencion}</p>}{decision.escenarioProcesal === "DELITO LEVE" && <p className="sp-status-note">Regla general: no detener. Excepción: art. 495 LECrim.</p>}</section> }
function Continuation({ decision, additionalItems = [] }: { decision: { situacion?: string }; additionalItems?: string[] }) { if (!decision.situacion) return null; const next = decision.situacion === "DETENIDO" ? ["Informar de derechos y garantías al detenido.", "Solicitar presencia de CNP en el lugar.", "Entregar persona y actuaciones a CNP."] : decision.situacion === "INVESTIGADO NO DETENIDO" ? ["Informar de hechos y derechos.", "Coordinar con CNP la continuación y citación.", "Comparecer posteriormente cuando corresponda."] : decision.situacion === "RUTA DE RESPONSABILIDAD PENAL DE MENORES" ? ["Activar el procedimiento específico de responsabilidad penal de menores y coordinar con la unidad competente."] : ["Continuar diligencias y comprobaciones a prevención.", "Comunicar las actuaciones a CNP o unidad competente."]; return <OperationalSection title="CONTINUACIÓN OPERATIVA" items={uniqueItems([...additionalItems, ...next])} /> }
function LegalFoundation({ normas, detalle }: { normas: string[]; detalle?: string }) { return <div className="sp-common"><CollapsibleSection title="Fundamento jurídico"><Checklist items={uniqueItems(normas)} />{detalle && <p>{detalle}</p>}</CollapsibleSection></div> }
function CommonProcessual({ showSubstance = false }: { showSubstance?: boolean }) { if (!showSubstance) return null; return <div className="sp-common"><CollapsibleSection title="Aprehensión de sustancia"><Checklist items={seguridadPublica.comunes.aprehension} /></CollapsibleSection></div> }
function Checklist({ items, title, note }: { items: string[]; title?: string; note?: string }) { return <div className="sp-checklist">{title && <h4>{title}</h4>}<ul>{items.map((item) => <li key={item}>{item}</li>)}</ul>{note && <p className="sp-note">{note}</p>}</div> }
const normalise = (value: string) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();

const uniqueItems = (items: string[]) => [...new Set(items)];
const isContinuationAction = (item: string) => /coordinar continuacion|continuacion.*CNP|presentar.*CNP|continuacion y citacion/i.test(normalise(item));
const isAttentionAction = (item: string) => /evitar interrogatorios|repeticiones innecesarias|no impide continuar/i.test(normalise(item));
const isIncidentAttention = (item: PublicSafetyOutcome["resultados"][number]) =>
  /DENUNCIA DE LA V[ÍI]CTIMA|NO VALORAR [ÚU]NICAMENTE COMO LESIONES|SUMISI[ÓO]N O VULNERABILIDAD QU[ÍI]MICA|V[ÍI]CTIMA MENOR DE 16 A[ÑN]OS/i.test(item.titulo);
const needsOutcomeDetail = (title: string) =>
  /CLASIFICACI[ÓO]N PROVISIONAL|INDIVIDUALIZAR CONDUCTAS|DATOS DE .*PENDIENTES|SIN AGRESI[ÓO]N F[ÍI]SICA|SIN ACTO SEXUAL/i.test(title);
const relationshipOptions: Array<[string, string]> = [["esposa", "Esposa"], ["exesposa", "Exesposa"], ["pareja", "Pareja con relación análoga de afectividad"], ["expareja", "Expareja con relación análoga de afectividad"], ["familiar", "Relación familiar"], ["conviviente", "Conviviente sin relación de pareja"], ["superioridad", "Relación de superioridad, autoridad o profesional"], ["amigo", "Amigo/a"], ["conocido", "Conocido/a"], ["desconocido", "Desconocido/a"], ["otra", "Otra relación"], ["no_determinada", "Relación no determinada"]];
const sexOptions: Array<[string, string]> = [["hombre", "Hombre"], ["mujer", "Mujer"], ["otro", "Otro"], ["no_determinado", "No determinado"]];
const sexualConductOptions: Array<[string, string]> = [["acto_fisico", "Acto sexual físico"], ["hacer_presenciar", "Hacer presenciar actos sexuales"], ["contacto_tic", "Contacto mediante internet, teléfono o TIC"]];
const consentOptions: Array<[string, string]> = [["ausencia_manifestada", "Consta manifestación de ausencia de consentimiento"], ["actos_claros_consentimiento", "Constan actos claros de consentimiento"], ["violencia_intimidacion", "Consta violencia o intimidación"], ["voluntad_anulada", "Consta voluntad anulada"], ["informacion_insuficiente", "Información todavía insuficiente"]];
const procedureOptions: Array<[string, string]> = [["denuncia_victima", "Denuncia de la persona agraviada, incluida denuncia oral formalizable"], ["denuncia_representante", "Denuncia del representante legal"], ["ministerio_fiscal", "Querella o actuación del Ministerio Fiscal"], ["pendiente", "Víctima adulta capaz no desea denunciar y no consta aún actuación fiscal"]];
const relationEvents: Array<[string, string]> = [["agresion", "Agresión física"], ["amenazas", "Amenazas"], ["coacciones", "Coacciones"], ["sexual", "Agresión sexual"], ["quebrantamiento", "Posible quebrantamiento de prohibición o medida"]];
const medicalResultOptions: Array<[string, string]> = [["sin_asistencia", "Todavía sin asistencia"], ["primera_asistencia", "Primera asistencia únicamente"], ["tratamiento_posterior", "Requiere tratamiento médico o quirúrgico posterior"], ["desconocido", "Se desconoce"]];
const fightTypeOptions: Array<[string, string]> = [["una_agrede", "Una persona agrede a otra"], ["reciproca", "Dos personas se agreden mutuamente"], ["grupal_confusa", "Varias personas o grupos se acometen de forma confusa"], ["grupal_individualizable", "Varias personas intervienen, pero pueden individualizarse claramente agresores y víctimas"]];
const freedomConductOptions: Array<[string, string]> = [["amenaza", "Anuncia que causará un mal"], ["coaccion", "Obliga a hacer algo o impide hacer algo"], ["acoso", "Conducta reiterada de vigilancia, persecución o contacto"]];
const threatHarmOptions: Array<[string, string]> = [["entidad_delictiva", "Muerte, lesión grave, agresión sexual u otro mal de esa entidad"], ["menor_entidad", "Mal de menor entidad"], ["no_precisado", "No puede concretarse todavía"]];
const coactionOptions: Array<[string, string]> = [["general", "Violencia o intimidación para obligar o impedir"], ["leve", "Imposición o impedimento de menor entidad"], ["no_precisada", "No puede concretarse todavía"]];
const trafficIndicators = ["Cantidad o naturaleza", "Forma de presentación o pluralidad de envoltorios", "Básculas, bolsas, material o sustancias de corte", "Dinero compatible con ventas", "Ventas, entregas o contactos observados", "Comunicaciones incorporables legítimamente", "Contexto, ocultación, condición de consumidor o explicación ofrecida"];
const weaponAvailability = [["encima", "La lleva encima"], ["efectos", "Está dentro de mochila, bolso, caja u otros efectos"], ["vehiculo", "Se encuentra en un vehículo"], ["sin_disponente", "No puede determinarse claramente quién dispone del objeto"]];
const weaponBehaviour = [["porte", "La lleva guardada / simplemente la porta"], ["manipula", "La manipula"], ["exhibe", "La exhibe"], ["intimidatoria", "La exhibe de forma intimidatoria"], ["amenaza", "Amenaza con ella"], ["intenta", "Intenta utilizarla contra otra persona"], ["usa", "La utiliza efectivamente contra otra persona"]];
const weaponContext = [["sin_incidente", "No existe otra conducta relacionada"], ["altercado", "Existe discusión o altercado"], ["violento", "Existe una situación violenta"], ["amenazas", "Se están produciendo amenazas o intimidación"], ["otro_delito", "Está relacionada con otro posible delito"], ["otras", "Existen otras circunstancias relevantes"]];
const weaponRelatedContext = weaponContext.filter(([id]) => id !== "sin_incidente");
const bladeTypes = [["navaja", "Navaja"], ["hoja", "Posible puñal"], ["cuchillo", "Cuchillo ordinario"], ["machete", "Machete"]];
const mechanismOptions = [["automatico", "Automático"], ["no_automatico", "No automático"], ["dudoso", "No puedo determinarlo con seguridad"]];
const manualLengthOptions = [["supera_11", "Sí, supera 11 cm"], ["no_supera_11", "No, no supera 11 cm"], ["dudosa", "No puedo determinarlo con seguridad"]];
const armamentOptions = [["aprobado", "Sí"], ["imitacion", "Parece una imitación de ese tipo"], ["no", "No"], ["dudoso", "No puedo determinarlo con seguridad"]];
const exceptionalTenureOptions = [["contemplacion", "Mera contemplación o examen"], ["reparacion", "Reparación"], ["transmision", "Simple transmisión a otra persona"], ["ninguna", "Ninguna de las anteriores"]];
const carryPurposeOptions = [["trabajo", "Trabajo"], ["actividad", "Actividad deportiva, caza o pesca"], ["trayecto", "Transporte hacia o desde una actividad relacionada"], ["otro", "Otro motivo concreto"], ["ninguno", "Ningún motivo concreto"], ["dudoso", "No puede determinarse"]];
const carryTransportOptions = [["funda", "En funda, caja o bolsa adecuada"], ["equipamiento", "Junto con herramientas o equipamiento relacionado"], ["mochila", "En mochila o bolso"], ["bolsillo", "En bolsillo, cintura o ropa"], ["accesible", "Inmediatamente accesible"], ["otro", "Otra situación"]];
const carryPlaceOptions = [["trabajo", "Lugar de trabajo relacionado"], ["actividad", "Actividad deportiva, caza o pesca relacionada"], ["trayecto", "Trayecto directo hacia o desde dicha actividad"], ["via_publica", "Vía pública sin relación aparente con esa actividad"], ["establecimiento", "Establecimiento público"], ["ocio", "Local o zona de ocio"], ["reunion", "Lugar de reunión, concentración o recreo"], ["otro", "Otro lugar"]];
const momentOptions = [["coherente", "Horario coherente con la actividad"], ["madrugada", "Madrugada sin actividad relacionada"], ["otro", "Otro momento"], ["dudoso", "No puede determinarse"]];
const yesNoUnknown = [["si", "Sí"], ["no", "No"], ["dudoso", "No puede determinarse"]];
